// === Tab: mySketch ===
let particles;
let msPressed;
let round;
let amount;
let timer;
let time;
let rounds;

function setup() {
	createCanvas(1300, 650);

	amount = 150;
	time = 30;
	rounds = 15;
	particles = new Array(amount * rounds);

	for (j = 0; j < particles.length; j++) {
			particles[j] = new Particle(color(0));
			particles[j].live = false;
	}
}

function draw() {
	background(255);
	if (msPressed) {
		for (j = 0; j < particles.length; j++) {
			particles[j].update();
			particles[j].draw();
		}
	}
	timer++;
}

class Particle {
	x;
	y;
	xVel;
	yVel;
	d;
	rotation;
	angle;
	c;
	live;

	constructor(c_) {
		x = random(0, width);
		y = -50;
		xVel = random(-1, 1);
		yVel = random(2, 5);
		d = map(yVel, 2, 5, 12, 20);
		rotation = random(0, 1);
		c = c_;
	}

	function update() {
		x += xVel;
		y += yVel;
		angle += rotation;

		if (y > height + (d / 2)) {
			live = false;
		}
	}

	function draw() {
		if (live) {
			pushMatrix();
			translate(x, y);
			fill(c);
			noStroke();
			rotate(radians(angle));
			rect(0, 0, d, d);
			popMatrix();
		}
	}
}

function mousePressed() {
	if (timer > time) {
		msPressed = true;
		if (round < rounds) {
			round++;
		} else {
			round = 1;
		}

		for(i = amount * round - amount; i < amount * round; i++) {
			let ran = floor(random(0, 3.999));
			if (ran == 0) {
				cc = color(255, 51, 51);
			} else if (ran == 1) {
				cc = color(0, 153, 51);
			} else if (ran == 2) {
				cc = color(102, 153, 255);
			} else if (ran == 3) {
				cc = color(255, 209, 26);
			}
			particles[i] = new Particle(cc);
			particles[i].live = true;
		}
		timer = 0;
	}
}

